import sys
import math
from heapq import heappop, heappush

def dist(p1, p2):
    return math.sqrt((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2)

def minimum_binary_tree(n, points):
    points.sort(key=lambda x: (-x[1], x[0]))
    if len(points) == 2:
        return dist(points[0], points[1])

    left = [points[0]]
    right = []
    min_heap = []
    for i in range(1, n):
        p = points[i]
        if p[0] < points[0][0]:
            heappush(min_heap, (dist(p, left[-1]), i, len(left) - 1, 'L'))
        else:
            heappush(min_heap, (dist(p, points[0]), i, 0, 'R'))
            right.append(p)

    used = [False] * n
    used[0] = True
    edges = 0
    total_length = 0.0

    while edges < n - 1:
        while min_heap and used[min_heap[0][1]]:
            heappop(min_heap)
        if not min_heap:
            return -1
        d, i, j, direction = heappop(min_heap)
        used[i] = True
        total_length += d
        edges += 1
        p = points[i]
        if direction == 'L':
            left.append(p)
            for k in range(len(right)):
                if not used[right[k][2]]:
                    heappush(min_heap, (dist(p, right[k]), right[k][2], i, 'R'))
        else:
            right.append((p[0], p[1], i))
            for k in range(len(left)):
                if not used[left[k][2]]:
                    heappush(min_heap, (dist(p, left[k]), left[k][2], i, 'L'))

    return total_length

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    points = [(int(input[2*i+1]), int(input[2*i+2])) for i in range(n)]
    result = minimum_binary_tree(n, points)
    if result == -1:
        print(-1)
    else:
        print(f"{result:.10f}")

if __name__ == "__main__":
    main()
